 @Test void crossActorHistoricalReadKeepsOriginalPublisherAndUsesCurrentReadProof()throws Exception{var saved=finish();String publisher=f.actor;f.end();f.actor=f.id(777);when(f.db.query(startsWith("SELECT created_by,idempotency_key"),any(RowMapper.class),any(Object[].class))).thenReturn(List.of(Map.entry(publisher,f.key)));f.begin();var historical=f.ledger.readPublishedAttempt(f.a,attempt.releaseId(),f.proof);assertEquals(f.actor,historical.actorId());assertEquals(publisher,f.ledger.row(historical).actor());f.end();var recovery=new RuntimeObjectTransport(()->writer,directory,16*1024*1024).transferVerified(historical,()->{});f.begin();assertEquals(saved,service.read(f.a,historical,recovery,f.proof));verify(writer).recoverVerified(any(),any());verify(f.proof,atLeastOnce()).requireRead(f.a);}
